583			// recursive self-import
584			{`import testdata/import_recursive0.txt`, true, [][]string{}},
585			{`import testdata/import_recursive3.txt
586			import testdata/import_recursive1.txt`, true, [][]string{}},
587	
588			// cyclic imports
589			{`(A) {
590				import A
591			}
592			:80
593			import A
594			`, true, [][]string{}},
595			{`(A) {
596				import B
597			}
598			(B) {
599				import A
600			}
601			:80
602			import A
603			`, true, [][]string{}},
604		} {
605			p := testParser(test.input)
606			blocks, err := p.parseAll()
607	
608			if test.shouldErr && err == nil {
609				t.Errorf("Test %d: Expected an error, but didn't get one", i)
610			}
611			if !test.shouldErr && err != nil {
612				t.Errorf("Test %d: Expected no error, but got: %v", i, err)
613			}
614	
615			if len(blocks) != len(test.keys) {
616				t.Errorf("Test %d: Expected %d server blocks, got %d",
617					i, len(test.keys), len(blocks))
618				continue
619			}
620			for j, block := range blocks {
621				if len(block.Keys) != len(test.keys[j]) {
622					t.Errorf("Test %d: Expected %d keys in block %d, got %d: %v",
623						i, len(test.keys[j]), j, len(block.Keys), block.Keys)
624					continue
625				}
626				for k, addr := range block.GetKeysText() {
627					if addr != test.keys[j][k] {
628						t.Errorf("Test %d, block %d, key %d: Expected '%s', but got '%s'",
629							i, j, k, test.keys[j][k], addr)
630					}
631				}
632			}
633		}
