399	// doImport swaps out the import directive and its argument
400	// (a total of 2 tokens) with the tokens in the specified file
401	// or globbing pattern. When the function returns, the cursor
402	// is on the token before where the import directive was. In
403	// other words, call Next() to access the first token that was
404	// imported.
405	func (p *parser) doImport(nesting int) error {
406		// syntax checks
407		if !p.NextArg() {
408			return p.ArgErr()
409		}
410		importPattern := p.Val()
411		if importPattern == "" {
412			return p.Err("Import requires a non-empty filepath")
413		}
414	
415		// grab remaining args as placeholder replacements
416		args := p.RemainingArgs()
417	
418		// set up a replacer for non-variadic args replacement
419		repl := makeArgsReplacer(args)
420	
421		// grab all the tokens (if it exists) from within a block that follows the import
422		var blockTokens []Token
423		for currentNesting := p.Nesting(); p.NextBlock(currentNesting); {
424			blockTokens = append(blockTokens, p.Token())
425		}
426		// initialize with size 1
427		blockMapping := make(map[string][]Token, 1)
428		if len(blockTokens) > 0 {
429			// use such tokens to create a new dispenser, and then use it to parse each block
430			bd := NewDispenser(blockTokens)
431	
432			// one iteration processes one sub-block inside the import
433			for bd.Next() {
434				currentMappingKey := bd.Val()
435	
436				if currentMappingKey == "{" {
437					return p.Err("anonymous blocks are not supported")
438				}
439	
440				// load up all arguments (if there even are any)
441				currentMappingTokens := bd.RemainingArgsAsTokens()
442	
443				// load up the entire block
444				for mappingNesting := bd.Nesting(); bd.NextBlock(mappingNesting); {
445					currentMappingTokens = append(currentMappingTokens, bd.Token())
446				}
447	
448				blockMapping[currentMappingKey] = currentMappingTokens
449			}
450		}
451	
452		// splice out the import directive and its arguments
453		// (2 tokens, plus the length of args)
454		tokensBefore := p.tokens[:p.cursor-1-len(args)-len(blockTokens)]
455		tokensAfter := p.tokens[p.cursor+1:]
456		var importedTokens []Token
457		var nodes []string
458	
459		// first check snippets. That is a simple, non-recursive replacement
460		if p.definedSnippets != nil && p.definedSnippets[importPattern] != nil {
461			importedTokens = p.definedSnippets[importPattern]
462			if len(importedTokens) > 0 {
463				// just grab the first one
464				nodes = append(nodes, fmt.Sprintf("%s:%s", importedTokens[0].File, importedTokens[0].snippetName))
465			}
466		} else {
467			// make path relative to the file of the _token_ being processed rather
468			// than current working directory (issue #867) and then use glob to get
469			// list of matching filenames
470			absFile, err := caddy.FastAbs(p.Dispenser.File())
471			if err != nil {
472				return p.Errf("Failed to get absolute path of file: %s: %v", p.Dispenser.File(), err)
473			}
474	
475			var matches []string
476			var globPattern string
477			if !filepath.IsAbs(importPattern) {
478				globPattern = filepath.Join(filepath.Dir(absFile), importPattern)
479			} else {
480				globPattern = importPattern
481			}
482			if strings.Count(globPattern, "*") > 1 || strings.Count(globPattern, "?") > 1 ||
483				(strings.Contains(globPattern, "[") && strings.Contains(globPattern, "]")) {
484				// See issue #2096 - a pattern with many glob expansions can hang for too long
485				return p.Errf("Glob pattern may only contain one wildcard (*), but has others: %s", globPattern)
486			}
487			matches, err = filepath.Glob(globPattern)
488			if err != nil {
489				return p.Errf("Failed to use import pattern %s: %v", importPattern, err)
490			}
491			if len(matches) == 0 {
492				if strings.ContainsAny(globPattern, "*?[]") {
493					caddy.Log().Warn("No files matching import glob pattern", zap.String("pattern", importPattern))
494				} else {
495					return p.Errf("File to import not found: %s", importPattern)
496				}
497			} else {
