501				if strings.HasPrefix(segGlobPattern[len(segGlobPattern)-1], "*") {
502					var tmpMatches []string
503					for _, m := range matches {
504						seg := strings.Split(m, sep)
505						if !strings.HasPrefix(seg[len(seg)-1], ".") {
506							tmpMatches = append(tmpMatches, m)
507						}
508					}
509					matches = tmpMatches
510				}
511			}
512	
513			// collect all the imported tokens
514			for _, importFile := range matches {
515				newTokens, err := p.doSingleImport(importFile)
516				if err != nil {
517					return err
518				}
519				importedTokens = append(importedTokens, newTokens...)
