type parser struct {
	*Dispenser
	block           ServerBlock // current server block being parsed
	eof             bool        // if we encounter a valid EOF in a hard place
	definedSnippets map[string][]Token
	nesting         int
	imports         importSource
	importGraph     importGraph
}

// importArgs is the stack of argument sets introduced by import
// statements that are actively being expanded. The entry at the top
// of the stack is the set visible to the current layer; arguments
// passed by an outer layer are hidden as soon as expansion enters
// a named snippet or another file.
type importArgs struct {
	args        []Token
	importing   string // normalized name of the file or snippet this layer expands
	isSnippet   bool
}

// argStack is a simple, parser-local stack. It is reset for every
// Parse call and never escapes the parser, so concurrent parses
// cannot observe one another's arguments.
type argStack []importArgs

func (s argStack) top() (importArgs, bool) {
	if len(s) == 0 {
		return importArgs{}, false
	}
	return s[len(s)-1], true
}

