		if rawStart == "" {
			ph.start = 0
		} else {
			index, err := parsePlaceholderIndex(rawStart)
			if err != nil {
				return argsPlaceholder{kind: argsVariadic}, true, err
			}
			ph.start = index
		}
		if rawEnd == "" {
			// open-ended ranges are bounded by the argument count later
			ph.end = -1
		} else {
			index, err := parsePlaceholderIndex(rawEnd)
			if err != nil {
				return argsPlaceholder{kind: argsVariadic}, true, err
			}
			ph.end = index
		}
		return ph, true, nil
	}

