func TestDbgNestedSnippet(t *testing.T) {
	tree := FileTree{
		"Caddyfile": []byte("import f\n:8080 {\n\timport t1 true\n}\n"),
		"f":         []byte("(t1) {\n\tbody {args[:]}\n}\n:8081 {\n\timport t1 false\n}\n"),
