13	// limitations under the License.
14	
15	package caddyfile
16	
17	import (
18		"fmt"
19		"strconv"
20		"strings"
21	)
22	
23	// argsPlaceholder kinds recognized by the import expansion.
24	type argsPlaceholderKind int
25	
26	const (
27		argsSingle    argsPlaceholderKind = iota // {args[N]} (or deprecated {args.N})
28		argsVariadic                              // {args[a:b]}
29	)
30	
31	// argsPlaceholder describes a parsed argument placeholder.
32	type argsPlaceholder struct {
33		kind      argsPlaceholderKind
34		start     int // inclusive start index (variadic and single)
35		end       int // exclusive end index (variadic only)
36		deprecated bool
37	}
38	
39	// parseArgsPlaceholder parses body, the text between the braces of a
40	// placeholder (for example "args[0]" or "args[1:3]"), and reports
41	// whether it is a well-formed argument placeholder. A body that is
42	// clearly meant to be one but has an illegal index is reported with
43	// ok == true and a non-nil err, so callers can reject the parse
44	// instead of silently leaving the text untouched.
45	func parseArgsPlaceholder(body string) (argsPlaceholder, bool, error) {
46		if strings.HasPrefix(body, "args[") && strings.HasSuffix(body, "]") {
47			inner := body[len("args[") : len(body)-len("]")]
48			if inner == "" {
49				return argsPlaceholder{}, true, fmt.Errorf("placeholder {args[]} cannot have an empty index")
50			}
51	
52			rawStart, rawEnd, hasRange := strings.Cut(inner, ":")
53			if !hasRange {
54				index, err := parsePlaceholderIndex(rawStart)
55				if err != nil {
56					return argsPlaceholder{kind: argsSingle}, true, err
57				}
58				return argsPlaceholder{kind: argsSingle, start: index, end: index + 1}, true, nil
59			}
60	
61			// more than one colon is never a valid range
62			if strings.Count(inner, ":") > 1 {
63				return argsPlaceholder{kind: argsVariadic}, true, fmt.Errorf("variadic placeholder {%s} has an invalid index range", body)
64			}
65	
66			ph := argsPlaceholder{kind: argsVariadic}
67			if rawStart == "" {
68				ph.start = 0
69			} else {
70				index, err := parsePlaceholderIndex(rawStart)
71				if err != nil {
72					return argsPlaceholder{kind: argsVariadic}, true, err
73				}
74				ph.start = index
75			}
76			if rawEnd == "" {
77				// open-ended ranges are bounded by the argument count later
78				ph.end = -1
79			} else {
80				index, err := parsePlaceholderIndex(rawEnd)
81				if err != nil {
82					return argsPlaceholder{kind: argsVariadic}, true, err
83				}
84				ph.end = index
85			}
86			return ph, true, nil
87		}
88	
89		// TODO: Remove the deprecated {args.*} placeholder support at
90		// some point in the future.
91		if strings.HasPrefix(body, "args.") && body != "args." {
92			index, err := parsePlaceholderIndex(strings.TrimPrefix(body, "args."))
93			if err != nil {
94				return argsPlaceholder{deprecated: true}, true, err
95			}
96			return argsPlaceholder{kind: argsSingle, start: index, end: index + 1, deprecated: true}, true, nil
97		}
98	
99		return argsPlaceholder{}, false, nil
100	}
101	
102	// parsePlaceholderIndex parses a single non-negative argument index.
103	func parsePlaceholderIndex(raw string) (int, error) {
104		index, err := strconv.Atoi(raw)
105		if err != nil || index < 0 {
106			return 0, fmt.Errorf("invalid argument index %q", raw)
107		}
108		return index, nil
109	}
110	
111	// looksLikeArgsPlaceholder reports whether body, the contents of a
112	// brace pair, was clearly intended as an argument placeholder but is
113	// malformed. Such text is an error instead of being kept verbatim.
114	func looksLikeArgsPlaceholder(body string) bool {
115		return body == "args" || body == "args." ||
116			strings.HasPrefix(body, "args[") || strings.HasPrefix(body, "args.")
117	}
118	
119	// wholeTokenPlaceholder parses text expecting it to contain exactly
120	// one argument placeholder and nothing else.
121	func wholeTokenPlaceholder(text string) (argsPlaceholder, bool, error) {
122		if len(text) < 2 || text[0] != '{' || text[len(text)-1] != '}' {
123			return argsPlaceholder{}, false, nil
124		}
125		body := text[1 : len(text)-1]
126		ph, ok, err := parseArgsPlaceholder(body)
127		if !ok {
128			// an args-like body inside a whole token is still a
129			// malformed attempt at a placeholder
130			if looksLikeArgsPlaceholder(body) {
131				return argsPlaceholder{}, true, fmt.Errorf("invalid argument placeholder {%s}", body)
132			}
133			return argsPlaceholder{}, false, nil
134		}
135		return ph, true, err
136	}
137	
138	// substituteImportArgs expands argument placeholders in one imported
139	// token. A whole-token placeholder is replaced with the argument
140	// token itself (so arguments containing spaces or quotes stay a
141	// single token, with their quoting intact); a placeholder embedded
142	// in surrounding text is substituted in place and can never cause
143	// re-tokenization.
144	//
145	// Ordinary braces, adjacent literal text, and braces escaped with a
146	// backslash are preserved verbatim. Malformed placeholders, indices
147	// out of range, and variadic placeholders embedded in other text are
148	// reported as errors, located at the imported token.
149	func substituteImportArgs(token Token, argTokens []Token) ([]Token, error) {
150		text := token.Text
151	
152		// fast path: the token is a single placeholder on its own
153		if ph, ok, err := wholeTokenPlaceholder(text); ok {
154			if err != nil {
155				return nil, importArgsErr(token, err.Error())
156			}
157			if ph.kind == argsSingle {
158				if ph.start >= len(argTokens) {
159					return nil, importArgsErr(token,
160						fmt.Sprintf("placeholder {args[%d]} is out of range: only %d argument(s) were given to the import", ph.start, len(argTokens)))
161				}
162				return []Token{positionArgToken(argTokens[ph.start], token)}, nil
163			}
164	
165			// variadic: validate the range against the available args
166			start, end, err := boundVariadic(ph, len(argTokens), text)
167			if err != nil {
168				return nil, importArgsErr(token, err.Error())
169			}
170			out := make([]Token, 0, end-start)
171			for _, arg := range argTokens[start:end] {
172				out = append(out, positionArgToken(arg, token))
173			}
174			return out, nil
175		}
176	
177		// slow path: scan the token for embedded placeholders
178		var sb strings.Builder
179		sb.Grow(len(text))
180		for i := 0; i < len(text); {
181			// escaped braces are literal braces; the escaping backslash
182			// is consumed so the brace is never re-expanded
183			if text[i] == '\\' && i+1 < len(text) && (text[i+1] == '{' || text[i+1] == '}') {
184				sb.WriteByte(text[i+1])
185				i += 2
186				continue
187			}
188	
189			if text[i] != '{' {
190				sb.WriteByte(text[i])
191				i++
192				continue
193			}
194	
195			closeRel := strings.IndexByte(text[i+1:], '}')
196			if closeRel < 0 {
197				// unmatched opening brace: the rest is ordinary text
198				sb.WriteString(text[i:])
199				break
200			}
201			end := i + 1 + closeRel
202			body := text[i+1 : end]
203	
204			ph, isArgs, parseErr := parseArgsPlaceholder(body)
205			if !isArgs {
206				if looksLikeArgsPlaceholder(body) {
207					return nil, importArgsErr(token, fmt.Sprintf("invalid argument placeholder {%s}", body))
208				}
209				// this brace pair is not an args placeholder (for
210				// example a JSON object), but an args placeholder may
211				// still be nested inside it; emit just the opening
212				// brace and rescan its contents
213				sb.WriteByte('{')
214				i++
215				continue
216			}
217			if parseErr != nil {
218				return nil, importArgsErr(token, parseErr.Error())
219			}
220			if ph.kind == argsVariadic {
221				return nil, importArgsErr(token, fmt.Sprintf("variadic placeholder {%s} must be a token on its own", body))
222			}
223			if ph.start >= len(argTokens) {
224				indexText := strconv.Itoa(ph.start)
225				if ph.deprecated {
226					return nil, importArgsErr(token,
227						fmt.Sprintf("placeholder {args.%s} is out of range: only %d argument(s) were given to the import", indexText, len(argTokens)))
228				}
229				return nil, importArgsErr(token,
230					fmt.Sprintf("placeholder {args[%s]} is out of range: only %d argument(s) were given to the import", indexText, len(argTokens)))
231			}
232	
233			// substitute only the argument's text, in place; quoting
234			// belongs to the surrounding token and is left untouched
235			sb.WriteString(argTokens[ph.start].Text)
236			i = end + 1
237		}
238	
239		out := token
240		out.Text = sb.String()
241		return []Token{out}, nil
242	}
243	
244	// boundVariadic resolves an open-ended variadic range and validates
245	// it against the number of available arguments.
246	func boundVariadic(ph argsPlaceholder, argCount int, text string) (int, int, error) {
247		start := ph.start
248		end := ph.end
249		if end == -1 {
250			end = argCount
251		}
252		if start > end {
253			return 0, 0, fmt.Errorf("variadic placeholder %s has a start index greater than its end index", text)
254		}
255		if end > argCount {
256			return 0, 0, fmt.Errorf("variadic placeholder %s is out of range: only %d argument(s) were given to the import", text, argCount)
257		}
258		return start, end, nil
259	}
260	
261	// positionArgToken returns a copy of a placeholder token carrying an
262	// argument's value. Location and import provenance stay attached to
263	// where the placeholder was written (so line adjacency and error
264	// locations are stable through nested imports), while the argument's
265	// exact text and quoting are preserved without re-tokenization.
266	func positionArgToken(arg, placeholder Token) Token {
267		t := placeholder.Clone()
268		t.Text = arg.Text
269		t.wasQuoted = arg.wasQuoted
270		t.quoteClosed = arg.quoteClosed
271		t.heredocMarker = arg.heredocMarker
272		return t
273	}
274	
275	// importArgsErr builds a parse error for a placeholder problem,
276	// pointing at the file and line where the placeholder was written.
277	func importArgsErr(token Token, msg string) error {
278		if len(token.imports) > 0 {
279			return fmt.Errorf("%s, at %s:%d import chain ['%s']",
280				msg, token.File, token.Line, strings.Join(token.imports, "','"))
281		}
282		return fmt.Errorf("%s, at %s:%d", msg, token.File, token.Line)
283	}
284	
285	// parseVariadic determines if the token is a variadic placeholder,
286	// and if so, determines the index range (start/end) of args to use.
287	// Returns a boolean signaling whether a variadic placeholder was found,
288	// and the start and end indices.
289	//
290	// Deprecated: retained for the unit-level predicate checks; expansion
291	// goes through substituteImportArgs, which also rejects malformed
292	// placeholders and out-of-range indices as hard parse errors.
293	func parseVariadic(token Token, argCount int) (bool, int, int) {
294		ph, ok, err := wholeTokenPlaceholder(token.Text)
295		if err != nil || !ok || ph.kind != argsVariadic {
296			return false, 0, 0
297		}
298		start, end, err := boundVariadic(ph, argCount, token.Text)
299		if err != nil {
300			return false, 0, 0
301		}
302		return true, start, end
303	}
