// concurrent parses with distinct trees over the same filenames
const workers = 32
const iterations = 20
var wg sync.WaitGroup
errCh := make(chan error, workers)
for w := 0; w < workers; w++ {
	wg.Add(1)
	go func(w int) {
		defer wg.Done()
		want := "worker"
		for i := 0; i < iterations; i++ {
			tree := mkTree(want)
			blocks, perr := Parse("Caddyfile", tree["Caddyfile"], tree)
			if perr != nil {
				errCh <- perr
				return
			}
			got := flattenBlocks(blocks)
			if len(got) != 1 || len(got[0]) != 2 || got[0][1] != want {
				errCh <- errors.New("parallel parse observed foreign arguments")
				return
			}
		}
	}(w)

