func TestImportArgsVariadic(t *testing.T) {
	tree := FileTree{
		"Caddyfile": []byte(":8080 {\n" +
			"\timport f.caddy one two three\n" +
			"}\n"),
		"f.caddy": []byte("all {args[:]}\n" +
			"tail {args[1:]}\n" +
			"span {args[0:2]}\n"),
	}
	lines, err := parseTree(t, tree)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	assertLines(t, [][]string{
		{"all", "one", "two", "three"},
		{"tail", "two", "three"},
		{"span", "one", "two"},
	}, lines)
}

