111	// looksLikeArgsPlaceholder reports whether body, the contents of a
112	// brace pair, was clearly intended as an argument placeholder but is
113	// malformed. Such text is an error instead of being kept verbatim.
114	func looksLikeArgsPlaceholder(body string) bool {
115		return body == "args" || body == "args." ||
116			strings.HasPrefix(body, "args[") || strings.HasPrefix(body, "args.")
117	}
